{"STAY_NIGHT","reg=law|st=neutral,careful",{"Your call, then"}},
{"STAY_NIGHT","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral|hour=16,22",{"Your call, offer's good until dusk"}},
{"STAY_NIGHT","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral|hour=16,5",{"Fine, but you'll regret it when it gets dark"}},
